function learnLogo(sym, url) {
  if (!sym || !url || LEARNED[sym] === url) return;
  WEB[sym] = [url];
  LEARNED[sym] = url;
  clearTimeout(saveTimer);
  saveTimer = setTimeout(() => {
    try { localStorage.setItem(LOGO_KEY, JSON.stringify(LEARNED)); } catch (e) {}
  }, 400);
}

